   <div class="card">${ch('Suggested Tasks',vAll)}<div class="px-2 pb-3">${['Continue UI improvements for dashboard','Complete pending design review items','Update project documentation'].map(t=>`<div class="flex items-center gap-3 px-2 py-2"><i data-lucide="lightbulb" class="w-4 h-4 text-amber-500 flex-none"></i><span class="flex-1 text-[11.5px] font-bold text-slate-700 leading-snug">${t}</span><button class="text-[11px] font-bold text-brand" data-toast="Task added">Add</button></div>`).join('')}</div></div>
