   <div class="px-4 flex gap-4 border-b border-slate-100 text-[12px] font-bold text-slate-400">${[['All',1],['Present',0],['Absent',0],['Half Day',0],['Leave',0]].map(([t,a])=>`<button class="pb-2.5 ${a?'text-brand border-b-2 border-brand -mb-px':''}">${t}</button>`).join('')}</div>
