function sendChat(){const inp=$('#chat-input');if(!inp||!inp.value.trim())return;const wrap=inp.closest('.flex').previousElementSibling;const d=document.createElement('div');d.className='flex';d.innerHTML=`<div class="msg-out"><p>${inp.value.replace(/</g,'&lt;')}</p><p class="text-[9px] text-slate-400 mt-1 text-right flex items-center justify-end gap-1">now <i data-lucide="check" class="w-3 h-3 text-slate-400"></i></p></div>`;wrap.appendChild(d);inp.value='';wrap.scrollTop=wrap.scrollHeight;lucide.createIcons();}

